package com.adesh.devjarvis.brain

/**
 * JARVIS ki badi skill library: 200+ chhote, pakke playbooks, area-wise. Inke ids tool description mein
 * poore nahi jaate (request chhoti rahe); brain `use_skill` ko id ya request ke shabd deta hai aur
 * [Skills.search] sahi skill dhoondh leta hai. Har playbook ke steps " | " se alag hain.
 */
internal object SkillLibrary {
    private class Builder(val area: String) {
        val out = mutableListOf<Skills.Skill>()
        fun s(id: String, whenToUse: String, steps: String) {
            val body = steps.split(" | ").mapIndexed { i, step -> "${i + 1}. ${step.trim()}" }.joinToString("\n")
            out += Skills.Skill(id, whenToUse, body, area)
        }
    }

    private fun area(name: String, block: Builder.() -> Unit): List<Skills.Skill> = Builder(name).apply(block).out

